-- GENERATED by tools/gen_context_sql.py; edit that script, not this file.
-- M2: venues, venue distances, and the leakage-safe game context view.

CREATE TABLE venues (
  venue_id    INTEGER PRIMARY KEY,
  league      TEXT NOT NULL,
  team_abbr   TEXT NOT NULL,
  name        TEXT NOT NULL,
  lat         REAL NOT NULL,
  lon         REAL NOT NULL,
  utc_offset  INTEGER NOT NULL,   -- standard-time offset; only differences between venues are used
  valid_from  TEXT,               -- ISO date, inclusive (NULL = always)
  valid_to    TEXT                -- ISO date, exclusive (NULL = still current)
);
CREATE TABLE venue_distances (
  from_venue  INTEGER NOT NULL REFERENCES venues(venue_id),
  to_venue    INTEGER NOT NULL REFERENCES venues(venue_id),
  km          REAL NOT NULL,
  PRIMARY KEY (from_venue, to_venue)
);
