-- Indexes that make the per-team ordering cheap
CREATE INDEX IF NOT EXISTS games_home_time ON games (home_team_id, start_time);
CREATE INDEX IF NOT EXISTS games_away_time ON games (away_team_id, start_time);

-- One row per team per game. Every value uses ONLY games scheduled before this one
-- (their start times and places are known in advance), never results, so it is safe to use
-- at prediction time. Postponed/canceled games are excluded (they weren't played then).
-- Limitation: a game's venue is the home team's arena (neutral sites such as international or
-- NBA Cup finals games aren't flagged yet).
CREATE VIEW game_team_context AS
WITH tg AS (
  SELECT g.id AS game_id, g.season, g.start_time, g.home_team_id AS team_id, g.away_team_id AS opponent_id, 1 AS is_home, h.abbr AS host_abbr
  FROM games g JOIN teams h ON h.id = g.home_team_id
  WHERE g.league = 'NBA' AND COALESCE(g.status, '') NOT IN ('postponed', 'canceled', 'abandoned')
  UNION ALL
  SELECT g.id, g.season, g.start_time, g.away_team_id, g.home_team_id, 0, h.abbr
  FROM games g JOIN teams h ON h.id = g.home_team_id
  WHERE g.league = 'NBA' AND COALESCE(g.status, '') NOT IN ('postponed', 'canceled', 'abandoned')
),
v AS (
  SELECT tg.*, (SELECT ve.venue_id FROM venues ve WHERE ve.league = 'NBA' AND ve.team_abbr = tg.host_abbr
                  AND (ve.valid_from IS NULL OR substr(tg.start_time, 1, 10) >= ve.valid_from)
                  AND (ve.valid_to IS NULL OR substr(tg.start_time, 1, 10) < ve.valid_to)) AS venue_id
  FROM tg
),
w AS (
  SELECT v.*,
    LAG(start_time) OVER (PARTITION BY team_id ORDER BY start_time, game_id) AS prev_start,
    LAG(season)     OVER (PARTITION BY team_id ORDER BY start_time, game_id) AS prev_season,
    LAG(venue_id)   OVER (PARTITION BY team_id ORDER BY start_time, game_id) AS prev_venue_id,
    COUNT(*) OVER (PARTITION BY team_id ORDER BY julianday(start_time) RANGE BETWEEN 7 PRECEDING AND 0.0001 PRECEDING) AS games_last_7d
  FROM v
)
SELECT w.game_id, w.season, w.start_time, w.team_id, w.opponent_id, w.is_home, w.venue_id,
  CASE WHEN w.prev_season = w.season THEN w.prev_start END AS prev_game_start,
  -- whole days between the two games' US Eastern calendar dates (UTC - 5h covers NBA tip times)
  CASE WHEN w.prev_season = w.season THEN CAST(julianday(date(w.start_time, '-5 hours')) - julianday(date(w.prev_start, '-5 hours')) AS INTEGER) - 1 END AS rest_days,
  CASE WHEN w.prev_season = w.season AND date(w.prev_start, '-5 hours') = date(w.start_time, '-5 hours', '-1 day') THEN 1 ELSE 0 END AS back_to_back,
  CASE WHEN w.prev_season IS NULL OR w.prev_season <> w.season THEN 1 ELSE 0 END AS first_game_of_season,
  w.games_last_7d,
  CASE WHEN w.prev_season = w.season THEN (SELECT d.km FROM venue_distances d WHERE d.from_venue = w.prev_venue_id AND d.to_venue = w.venue_id) END AS travel_km,
  CASE WHEN w.prev_season = w.season THEN (SELECT b.utc_offset - a.utc_offset FROM venues a, venues b WHERE a.venue_id = w.prev_venue_id AND b.venue_id = w.venue_id) END AS tz_shift_hours
FROM w;
